const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    // Define China geometry from a public dataset to ensure consistency
    const china = ee.FeatureCollection('FAO/GAUL/2015/level0')
      .filter(ee.Filter.eq('ADM0_NAME', 'China'))
      .geometry();

    const year2000_start = '2000-01-01';
    const year2000_end = '2000-12-31';
    const year2017_start = '2017-01-01';
    const year2017_end = '2017-12-31';

    // Scale for reduceRegion. MODIS resolution is 250m,
    // using 1000m or more for large area to avoid memory errors.
    const scale = 1000;

    // Function to mask clouds and low quality pixels
    function maskModisNdvi(image) {
      // Select the QA band
      const qa = image.select('QA');

      // Bits 0-1 are `MODLAND_QA`: 00 = Good data, 01 = Marginal data, 10 = Saturated, 11 = Cloud.
      // We want to keep 00 (Good data)
      const modland_qa = qa.rightShift(0).mod(4); // Extract bits 0-1

      // Bits 2-5 are `VI_QUALITY`: 0000 = VI produced, good quality.
      // We want to keep 0000
      const vi_quality = qa.rightShift(2).mod(16); // Extract bits 2-5

      // Mask out bad pixels: modland_qa is not 00 (good data) OR vi_quality is not 0000 (good quality)
      const mask = modland_qa.eq(0).and(vi_quality.eq(0));

      // Apply the mask and scale the NDVI band
      const ndvi = image.select('NDVI').divide(10000);

      // Mask out non-vegetation or invalid NDVI values (-0.2 to 1.0)
      const validNdvi = ndvi.updateMask(mask).clamp(-0.2, 1.0);

      return image.addBands(validNdvi.rename('NDVI_masked'));
    }

    // 2. Data Acquisition & Check
    let collection2000 = ee.ImageCollection('MODIS/051/MOD13Q1')
      .filterDate(year2000_start, year2000_end)
      .filterBounds(china)
      .map(maskModisNdvi)
      .select('NDVI_masked');

    let collection2017 = ee.ImageCollection('MODIS/051/MOD13Q1')
      .filterDate(year2017_start, year2017_end)
      .filterBounds(china)
      .map(maskModisNdvi)
      .select('NDVI_masked');

    const size2000 = await collection2000.size().getInfo();
    const size2017 = await collection2017.size().getInfo();

    if (size2000 === 0) {
      console.log(`2000 Images: ${size2000}`);
      console.log('No images found for 2000 after filtering.');
      console.log('C1');
      return;
    }
    if (size2017 === 0) {
      console.log(`2017 Images: ${size2017}`);
      console.log('No images found for 2017 after filtering.');
      console.log('C1');
      return;
    }

    // 3. Processing
    // Create annual median composites
    const annualNdvi2000 = collection2000.median().clip(china);
    const annualNdvi2017 = collection2017.median().clip(china);

    // Calculate valid pixel count for 2000
    const count2000 = await annualNdvi2000.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: china,
      scale: scale,
      maxPixels: 1e9,
    }).get('NDVI_masked').getInfo();

    // Calculate valid pixel count for 2017
    const count2017 = await annualNdvi2017.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: china,
      scale: scale,
      maxPixels: 1e9,
    }).get('NDVI_masked').getInfo();

    if (count2000 === 0 || count2000 === null) {
      console.log(`2000 Images: ${size2000} (Valid Pixels: ${count2000})`);
      console.log('No valid pixels remaining for 2000 after masking and clipping.');
      console.log('C2');
      return;
    }
    if (count2017 === 0 || count2017 === null) {
      console.log(`2017 Images: ${size2017} (Valid Pixels: ${count2017})`);
      console.log('No valid pixels remaining for 2017 after masking and clipping.');
      console.log('C2');
      return;
    }

    // 4. Calculation
    // Calculate mean NDVI for China for each year
    const meanNdvi2000 = await annualNdvi2000.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: china,
      scale: scale,
      maxPixels: 1e9,
    }).get('NDVI_masked').getInfo();

    const meanNdvi2017 = await annualNdvi2017.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: china,
      scale: scale,
      maxPixels: 1e9,
    }).get('NDVI_masked').getInfo();

    // 5. Validation & Final Answer
    if (meanNdvi2000 === null || isNaN(meanNdvi2000) ||
        meanNdvi2017 === null || isNaN(meanNdvi2017)) {
      console.log(`2000 Mean NDVI: ${meanNdvi2000}, 2017 Mean NDVI: ${meanNdvi2017}`);
      console.log('Calculation resulted in None or NaN.');
      console.log('C3');
      return;
    }

    console.log(`2000 Images: ${size2000} (Valid Pixels: ${count2000})`);
    console.log(`2017 Images: ${size2017} (Valid Pixels: ${count2017})`);
    console.log(`2000 Mean NDVI: ${meanNdvi2000.toFixed(3)}`);
    console.log(`2017 Mean NDVI: ${meanNdvi2017.toFixed(3)}`);

    if (meanNdvi2017 > meanNdvi2000) {
      console.log('A'); // Green leaf area increased
    } else {
      console.log('B'); // Green leaf area did not increase or decreased
    }

  } catch (e) {
    console.error('An error occurred: ', e);
    console.log('D'); // Catch-all for other errors like syntax, memory, etc.
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
